20	\vspace{-3mm}
21	\caption{Combo gain vs.\ capability gap (verifier standalone $-$ generator SC) at $w{=}3$. Meaningful gain emerges when the gap is positive (verifier exceeds generator).}
22	\label{fig:capability-gap}
23	\vspace{-6mm}
24	\end{figure}
